import React, { useState, useEffect } from 'react';
import { Brain, Leaf, Lightbulb, Target, TrendingUp, Zap } from 'lucide-react';
import Navigation from '../components/Navigation';
import { aiService, actionsService } from '../services/auth';

const AIRecommendations = ({ user, onLogout }) => {
  const [recommendations, setRecommendations] = useState([]);
  const [impactPrediction, setImpactPrediction] = useState(null);
  const [loading, setLoading] = useState(true);
  const [predictionLoading, setPredictionLoading] = useState(false);
  const [actionDescription, setActionDescription] = useState('');

  useEffect(() => {
    fetchRecommendations();
  }, []);

  const fetchRecommendations = async () => {
    try {
      setLoading(true);
      const response = await aiService.getRecommendations();
      setRecommendations(response);
    } catch (error) {
      console.error('Error fetching recommendations:', error);
      // Mock data for demo
      setRecommendations([
        {
          id: 1,
          title: 'Switch to LED Bulbs',
          description: 'Replace 5 incandescent bulbs with LED equivalents in your most-used rooms',
          impact_score: 25,
          difficulty: 'Easy',
          category: 'Energy Saving',
          time_estimate: '30 minutes',
          cost_estimate: '$50-75',
          co2_savings: '180 kg/year',
          reasons: [
            'Based on your energy usage patterns',
            'High impact, low effort action',
            'Immediate savings on electricity bills'
          ]
        },
        {
          id: 2,
          title: 'Start Composting Food Scraps',
          description: 'Set up a simple composting system for kitchen vegetable scraps and yard waste',
          impact_score: 35,
          difficulty: 'Medium',
          category: 'Waste Reduction',
          time_estimate: '2 hours setup',
          cost_estimate: '$20-40',
          co2_savings: '300 kg/year',
          reasons: [
            'Reduces methane emissions from landfills',
            'Creates nutrient-rich soil for gardening',
            'Matches your sustainability interests'
          ]
        },
        {
          id: 3,
          title: 'Bike to Work Twice a Week',
          description: 'Replace car trips with bicycle commuting for short-distance travel',
          impact_score: 45,
          difficulty: 'Medium',
          category: 'Transportation',
          time_estimate: 'Ongoing',
          cost_estimate: '$200-500 (bike)',
          co2_savings: '520 kg/year',
          reasons: [
            'Your commute distance is bike-friendly',
            'Improves health while reducing emissions',
            'Growing bike infrastructure in your area'
          ]
        },
        {
          id: 4,
          title: 'Reduce Meat Consumption',
          description: 'Try "Meatless Monday" and one additional plant-based meal per week',
          impact_score: 30,
          difficulty: 'Easy',
          category: 'Diet',
          time_estimate: 'Meal planning',
          cost_estimate: 'Save $10-15/week',
          co2_savings: '240 kg/year',
          reasons: [
            'Livestock farming has high carbon footprint',
            'Plant-based meals can be cost-effective',
            'Opportunity to try new recipes'
          ]
        }
      ]);
    } finally {
      setLoading(false);
    }
  };

  const predictImpact = async (e) => {
    e.preventDefault();
    if (!actionDescription.trim()) return;

    setPredictionLoading(true);

    console.log('Predicting impact for:', actionDescription); // Debug log

    // Smart impact prediction based on keywords
    const analyzeActionImpact = (description) => {
      const text = description.toLowerCase();
      let co2Savings = 0;
      let impactScore = 0;
      let category = 'Sustainability';
      let feasibility = 'Medium';
      let benefits = [];
      let similarActions = [];

      // Transportation actions
      if (text.includes('bike') || text.includes('bicycle') || text.includes('cycling')) {
        co2Savings = 520;
        impactScore = 75;
        category = 'Transportation';
        feasibility = 'High';
        benefits = ['Reduces transportation emissions', 'Improves personal health', 'Saves money on fuel'];
        similarActions = ['Use public transportation', 'Work from home', 'Electric vehicle'];
      }
      else if (text.includes('car') || text.includes('vehicle') || text.includes('electric') || text.includes('hybrid')) {
        co2Savings = 2400;
        impactScore = 85;
        category = 'Transportation';
        feasibility = 'Medium';
        benefits = ['Significantly reduces transportation emissions', 'Lower fuel costs', 'Advanced technology adoption'];
        similarActions = ['Bike to work', 'Use public transport', 'Carpool'];
      }
      else if (text.includes('public transport') || text.includes('bus') || text.includes('train')) {
        co2Savings = 1200;
        impactScore = 70;
        category = 'Transportation';
        feasibility = 'High';
        benefits = ['Reduces individual carbon footprint', 'Cost-effective travel', 'Reduces traffic congestion'];
        similarActions = ['Bike commuting', 'Electric vehicle', 'Walking'];
      }

      // Energy actions
      else if (text.includes('solar') || text.includes('renewable') || text.includes('wind energy')) {
        co2Savings = 3200;
        impactScore = 90;
        category = 'Energy';
        feasibility = 'Medium';
        benefits = ['Clean renewable energy', 'Long-term cost savings', 'Energy independence'];
        similarActions = ['LED lighting', 'Energy efficient appliances', 'Home insulation'];
      }
      else if (text.includes('led') || text.includes('light') || text.includes('bulb')) {
        co2Savings = 180;
        impactScore = 45;
        category = 'Energy';
        feasibility = 'High';
        benefits = ['Reduces electricity usage', 'Lower energy bills', 'Longer bulb lifespan'];
        similarActions = ['Smart thermostats', 'Unplug devices', 'Solar panels'];
      }

      // Diet/Food actions
      else if (text.includes('veg') || text.includes('plant') || text.includes('meat') || text.includes('vegetarian')) {
        co2Savings = 480;
        impactScore = 65;
        category = 'Diet & Food';
        feasibility = 'High';
        benefits = ['Reduces livestock emissions', 'Healthier diet', 'Cost savings on meat'];
        similarActions = ['Buy local food', 'Reduce food waste', 'Grow your own vegetables'];
      }
      else if (text.includes('local') || text.includes('organic') || text.includes('farmer')) {
        co2Savings = 240;
        impactScore = 55;
        category = 'Diet & Food';
        feasibility = 'High';
        benefits = ['Reduces food miles', 'Supports local economy', 'Fresher produce'];
        similarActions = ['Vegetarian meals', 'Seasonal eating', 'Home gardening'];
      }

      // Waste actions
      else if (text.includes('recycle') || text.includes('recycling')) {
        co2Savings = 120;
        impactScore = 40;
        category = 'Waste Reduction';
        feasibility = 'High';
        benefits = ['Diverts waste from landfills', 'Conserves resources', 'Easy habit to adopt'];
        similarActions = ['Reduce single-use items', 'Compost', 'Reusable bags'];
      }
      else if (text.includes('compost') || text.includes('composting')) {
        co2Savings = 300;
        impactScore = 60;
        category = 'Waste Reduction';
        feasibility = 'Medium';
        benefits = ['Reduces methane emissions', 'Creates nutrient-rich soil', 'Reduces food waste'];
        similarActions = ['Recycling', 'Food waste reduction', 'Worm farming'];
      }

      // Water actions
      else if (text.includes('water') || text.includes('shower') || text.includes('irrigation')) {
        co2Savings = 80;
        impactScore = 35;
        category = 'Water Conservation';
        feasibility = 'High';
        benefits = ['Conserves water resources', 'Reduces water heating energy', 'Lower utility bills'];
        similarActions = ['Rainwater harvesting', 'Drought-resistant plants', 'Fix leaks'];
      }

      // Default case
      else {
        co2Savings = 150;
        impactScore = 50;
        category = 'General Sustainability';
        feasibility = 'Medium';
        benefits = ['Positive environmental impact', 'Sustainable lifestyle choice', 'Sets good example'];
        similarActions = ['Energy conservation', 'Waste reduction', 'Sustainable transport'];
      }

      return {
        estimated_co2_savings: co2Savings,
        impact_score: impactScore,
        category: category,
        feasibility: feasibility,
        long_term_benefits: benefits,
        similar_actions: similarActions
      };
    };

    try {
      // Use smart local prediction directly (skipping API for reliability)
      console.log('Analyzing action:', actionDescription);
      const prediction = analyzeActionImpact(actionDescription);
      console.log('Local prediction result:', prediction); // Debug log

      // Ensure we have all required fields with fallbacks
      const safePrediction = {
        estimated_co2_savings: prediction.estimated_co2_savings || 150,
        impact_score: prediction.impact_score || 50,
        feasibility: prediction.feasibility || 'Medium',
        category: prediction.category || 'General Sustainability',
        long_term_benefits: prediction.long_term_benefits || ['Positive environmental impact'],
        similar_actions: prediction.similar_actions || []
      };

      console.log('Setting safe prediction:', safePrediction);
      setImpactPrediction(safePrediction);
    } catch (error) {
      console.error('Error in local prediction analysis:', error);
      // Ultimate fallback
      const fallbackPrediction = {
        estimated_co2_savings: 150,
        impact_score: 50,
        feasibility: 'Medium',
        category: 'General Sustainability',
        long_term_benefits: ['Positive environmental impact', 'Sustainable lifestyle choice'],
        similar_actions: ['Energy conservation', 'Waste reduction']
      };
      setImpactPrediction(fallbackPrediction);
    } finally {
      setPredictionLoading(false);
    }
  };

  const getDifficultyColor = (difficulty) => {
    switch (difficulty?.toLowerCase()) {
      case 'easy': return 'bg-green-100 text-green-800';
      case 'medium': return 'bg-yellow-100 text-yellow-800';
      case 'hard': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getCategoryIcon = (category) => {
    switch (category?.toLowerCase()) {
      case 'energy saving': return '⚡';
      case 'transportation': return '🚲';
      case 'waste reduction': return '♻️';
      case 'diet': return '🥗';
      case 'water conservation': return '💧';
      default: return '🌱';
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-eco-light">
        <Navigation user={user} onLogout={onLogout} />
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-primary"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-eco-light">
      <Navigation user={user} onLogout={onLogout} />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="mb-10">
          <div className="flex items-center mb-4">
            <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-blue-600 rounded-2xl flex items-center justify-center mr-4">
              <Brain className="h-6 w-6 text-white" />
            </div>
            <div>
              <h1 className="text-4xl font-bold bg-gradient-to-r from-green-secondary to-green-primary bg-clip-text text-transparent">
                AI Eco Recommendations
              </h1>
              <p className="text-gray-600 text-lg mt-1">Get personalized suggestions powered by artificial intelligence</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-6">
            <div className="bg-gradient-to-r from-green-100 to-green-200 rounded-xl p-4">
              <div className="flex items-center">
                <div className="w-8 h-8 bg-green-600 rounded-lg flex items-center justify-center mr-3">
                  <Leaf className="h-4 w-4 text-white" />
                </div>
                <div>
                  <h3 className="font-semibold text-green-800">Smart Analysis</h3>
                  <p className="text-sm text-green-700">AI-powered impact predictions</p>
                </div>
              </div>
            </div>
            <div className="bg-gradient-to-r from-blue-100 to-blue-200 rounded-xl p-4">
              <div className="flex items-center">
                <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center mr-3">
                  <Target className="h-4 w-4 text-white" />
                </div>
                <div>
                  <h3 className="font-semibold text-blue-800">Personalized</h3>
                  <p className="text-sm text-blue-700">Tailored to your lifestyle</p>
                </div>
              </div>
            </div>
            <div className="bg-gradient-to-r from-purple-100 to-purple-200 rounded-xl p-4">
              <div className="flex items-center">
                <div className="w-8 h-8 bg-purple-600 rounded-lg flex items-center justify-center mr-3">
                  <TrendingUp className="h-4 w-4 text-white" />
                </div>
                <div>
                  <h3 className="font-semibold text-purple-800">Real Impact</h3>
                  <p className="text-sm text-purple-700">Measurable CO2 reduction</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Recommendations List */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white rounded-xl p-6 mb-6 shadow-md border border-gray-100">
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <div className="w-10 h-10 bg-gradient-to-br from-green-500 to-green-600 rounded-xl flex items-center justify-center mr-3">
                    <Lightbulb className="h-5 w-5 text-white" />
                  </div>
                  <div>
                    <h2 className="text-2xl font-bold text-green-secondary">Personalized Recommendations</h2>
                    <p className="text-sm text-gray-600">AI-curated actions for maximum impact</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-3xl font-bold text-green-primary">{Array.isArray(recommendations) ? recommendations.length : 0}</span>
                  <p className="text-xs text-gray-500">Available Actions</p>
                </div>
              </div>
            </div>

            {Array.isArray(recommendations) && recommendations.map((rec) => (
              <div key={rec.id} className="bg-white rounded-xl shadow-md p-6 hover:shadow-xl transition-all duration-300 border border-gray-100 hover:border-green-200">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-start space-x-4">
                    <div className="w-12 h-12 bg-gradient-to-br from-green-100 to-eco-light rounded-xl flex items-center justify-center text-2xl">
                      {getCategoryIcon(rec.category)}
                    </div>
                    <div className="flex-1">
                      <h3 className="text-xl font-bold text-green-secondary mb-2">{rec.title}</h3>
                      <p className="text-gray-600 text-sm mb-3 leading-relaxed">{rec.description}</p>
                      <div className="flex items-center space-x-3 text-xs">
                        <span className={`px-3 py-1 rounded-full font-semibold ${getDifficultyColor(rec.difficulty)}`}>
                          {rec.difficulty}
                        </span>
                        <span className="px-3 py-1 bg-gray-100 text-gray-700 rounded-full font-medium">{rec.category}</span>
                        <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full font-semibold">{rec.co2_savings}</span>
                      </div>
                    </div>
                  </div>
                  <div className="text-center bg-gradient-to-br from-green-50 to-green-100 rounded-xl p-4 min-w-[80px]">
                    <div className="text-3xl font-bold text-green-primary">{rec.impact_score}</div>
                    <div className="text-xs text-green-600 font-medium">Impact</div>
                    <div className="text-xs text-gray-500">Score</div>
                  </div>
                </div>

                {/* Action Details */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4 text-sm">
                  <div className="flex items-center space-x-2">
                    <Target className="h-4 w-4 text-gray-400" />
                    <span className="text-gray-600">Time: {rec.time_estimate}</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <TrendingUp className="h-4 w-4 text-gray-400" />
                    <span className="text-gray-600">Cost: {rec.cost_estimate}</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Zap className="h-4 w-4 text-gray-400" />
                    <span className="text-gray-600">Annual Savings: {rec.co2_savings}</span>
                  </div>
                </div>

                {/* AI Reasoning */}
                <div className="mb-4">
                  <h4 className="text-sm font-medium text-gray-700 mb-2">Why this recommendation?</h4>
                  <ul className="space-y-1">
                    {Array.isArray(rec.reasons) && rec.reasons.map((reason, index) => (
                      <li key={index} className="flex items-start space-x-2 text-sm text-gray-600">
                        <Lightbulb className="h-3 w-3 text-yellow-500 mt-0.5 flex-shrink-0" />
                        <span>{reason}</span>
                      </li>
                    ))}
                  </ul>
                </div>

                {/* Action Buttons */}
                <div className="flex space-x-3 pt-4 border-t border-gray-100">
                  <button className="flex-1 py-3 bg-gradient-to-r from-green-primary to-green-600 text-white rounded-lg hover:from-green-600 hover:to-green-700 transition-all duration-200 font-medium shadow-md hover:shadow-lg">
                    Start This Action
                  </button>
                  <button className="px-6 py-3 border-2 border-green-primary text-green-primary rounded-lg hover:bg-green-50 transition-all duration-200 font-medium">
                    Learn More
                  </button>
                </div>
              </div>
            ))}
          </div>

          {/* Impact Predictor Sidebar */}
          <div className="space-y-6">
            <div className="bg-white rounded-xl shadow-lg p-6 border border-gray-100">
              <div className="flex items-center mb-6">
                <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-blue-600 rounded-xl flex items-center justify-center mr-3">
                  <Brain className="h-5 w-5 text-white" />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-green-secondary">AI Impact Predictor</h3>
                  <p className="text-sm text-gray-600">Analyze your eco-action potential</p>
                </div>
              </div>

              <form onSubmit={predictImpact} className="space-y-6">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-3">
                    Describe your planned eco action:
                  </label>
                  <textarea
                    value={actionDescription}
                    onChange={(e) => setActionDescription(e.target.value)}
                    placeholder="E.g., Installing solar panels on my roof, starting a vegetable garden, switching to electric vehicle, composting kitchen waste..."
                    rows={4}
                    className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-green-primary focus:border-green-primary resize-none transition-all duration-200 text-sm leading-relaxed"
                    required
                  />
                </div>

                <button
                  type="submit"
                  disabled={predictionLoading || !actionDescription.trim()}
                  className="w-full py-3 bg-gradient-to-r from-green-primary to-green-600 text-white rounded-xl hover:from-green-600 hover:to-green-700 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed font-semibold shadow-lg hover:shadow-xl"
                >
                  {predictionLoading ? (
                    <div className="flex items-center justify-center">
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                      Analyzing Impact...
                    </div>
                  ) : (
                    <div className="flex items-center justify-center">
                      <Brain className="h-4 w-4 mr-2" />
                      Predict Environmental Impact
                    </div>
                  )}
                </button>
              </form>

              {/* Quick Action Examples */}
              <div className="mt-6 p-4 bg-gray-50 rounded-xl">
                <h4 className="text-sm font-semibold text-gray-700 mb-3">Quick Examples:</h4>
                <div className="grid grid-cols-2 gap-2">
                  {['Solar panels', 'Electric car', 'Composting', 'LED lights'].map((example) => (
                    <button
                      key={example}
                      onClick={() => setActionDescription(example.toLowerCase())}
                      className="px-3 py-2 text-xs bg-white border border-gray-200 rounded-lg hover:border-green-300 hover:bg-green-50 transition-all duration-200"
                    >
                      {example}
                    </button>
                  ))}
                </div>
              </div>

              {/* Prediction Results */}
              {impactPrediction && (
                <div className="mt-6 p-6 bg-gradient-to-br from-green-50 to-eco-light rounded-xl border border-green-200 shadow-sm">
                  <div className="flex items-center mb-4">
                    <div className="w-8 h-8 bg-green-primary rounded-full flex items-center justify-center mr-3">
                      <TrendingUp className="h-4 w-4 text-white" />
                    </div>
                    <h4 className="font-semibold text-green-secondary">Impact Analysis Results</h4>
                  </div>

                  {/* Main Metrics */}
                  <div className="grid grid-cols-1 gap-4 mb-4">
                    <div className="bg-white rounded-lg p-4 shadow-sm">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center">
                          <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center mr-3">
                            <span className="text-green-600 font-bold text-lg">🌱</span>
                          </div>
                          <div>
                            <p className="text-sm text-gray-600">Annual CO2 Reduction</p>
                            <p className="text-2xl font-bold text-green-primary">{impactPrediction.estimated_co2_savings || 'N/A'}</p>
                            <p className="text-xs text-gray-500">kg per year</p>
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                      <div className="bg-white rounded-lg p-3 shadow-sm">
                        <p className="text-xs text-gray-600 mb-1">Impact Score</p>
                        <div className="flex items-center">
                          <div className="flex-1 bg-gray-200 rounded-full h-2 mr-2">
                            <div 
                              className="bg-gradient-to-r from-green-400 to-green-600 h-2 rounded-full transition-all duration-500"
                              style={{width: `${impactPrediction.impact_score || 0}%`}}
                            ></div>
                          </div>
                          <span className="font-bold text-sm">{impactPrediction.impact_score || 'N/A'}/100</span>
                        </div>
                      </div>

                      <div className="bg-white rounded-lg p-3 shadow-sm">
                        <p className="text-xs text-gray-600 mb-1">Feasibility</p>
                        <span className={`inline-flex px-3 py-1 text-xs font-medium rounded-full ${
                          impactPrediction.feasibility === 'High' ? 'bg-green-100 text-green-800' :
                          impactPrediction.feasibility === 'Medium' ? 'bg-yellow-100 text-yellow-800' :
                          'bg-red-100 text-red-800'
                        }`}>
                          {impactPrediction.feasibility || 'N/A'}
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Category Badge */}
                  {impactPrediction.category && (
                    <div className="mb-4">
                      <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                        <Target className="h-3 w-3 mr-1" />
                        {impactPrediction.category}
                      </span>
                    </div>
                  )}

                  {/* Benefits Section */}
                  {impactPrediction.long_term_benefits && Array.isArray(impactPrediction.long_term_benefits) && (
                    <div className="bg-white rounded-lg p-4 shadow-sm">
                      <h5 className="text-sm font-semibold text-gray-700 mb-3 flex items-center">
                        <Lightbulb className="h-4 w-4 text-yellow-500 mr-2" />
                        Key Benefits
                      </h5>
                      <ul className="space-y-2">
                        {impactPrediction.long_term_benefits.map((benefit, index) => (
                          <li key={index} className="text-sm text-gray-600 flex items-start space-x-2">
                            <div className="w-5 h-5 bg-green-100 rounded-full flex items-center justify-center mt-0.5 flex-shrink-0">
                              <span className="text-green-600 text-xs">✓</span>
                            </div>
                            <span>{benefit}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Quick Stats */}
            <div className="bg-white rounded-xl shadow-lg p-6 border border-gray-100">
              <div className="flex items-center mb-6">
                <div className="w-10 h-10 bg-gradient-to-br from-green-500 to-eco-primary rounded-xl flex items-center justify-center mr-3">
                  <TrendingUp className="h-5 w-5 text-white" />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-green-secondary">Your Progress</h3>
                  <p className="text-sm text-gray-600">Track your eco-journey</p>
                </div>
              </div>

              <div className="space-y-4">
                <div className="bg-gradient-to-r from-blue-50 to-blue-100 rounded-lg p-4">
                  <div className="flex justify-between items-center">
                    <span className="text-sm font-medium text-gray-700">Actions Completed</span>
                    <span className="text-2xl font-bold text-blue-600">12</span>
                  </div>
                </div>
                <div className="bg-gradient-to-r from-green-50 to-green-100 rounded-lg p-4">
                  <div className="flex justify-between items-center">
                    <span className="text-sm font-medium text-gray-700">CO2 Saved This Month</span>
                    <span className="text-2xl font-bold text-green-600">45 <span className="text-sm">kg</span></span>
                  </div>
                </div>
                <div className="bg-gradient-to-r from-purple-50 to-purple-100 rounded-lg p-4">
                  <div className="flex justify-between items-center">
                    <span className="text-sm font-medium text-gray-700">Success Rate</span>
                    <span className="text-2xl font-bold text-purple-600">67%</span>
                  </div>
                  <div className="mt-2 bg-purple-200 rounded-full h-2">
                    <div className="bg-purple-600 h-2 rounded-full" style={{width: '67%'}}></div>
                  </div>
                </div>
              </div>

              <div className="mt-6 p-4 bg-gradient-to-r from-green-100 to-eco-light rounded-xl border border-green-200">
                <div className="flex items-center">
                  <span className="text-2xl mr-3">🏆</span>
                  <div>
                    <p className="font-semibold text-green-800">Top 20% Eco-Warrior!</p>
                    <p className="text-sm text-green-700">You're making a real difference this month</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AIRecommendations;
